[13/14/15 Regression] ICE during IPA pass: targetclone in add_to_same_comdat_group with calling a target clone with a lamdba in a comdat function
Createdattachment 58133[details]outcome of -freport-bug

Since GCC 13.1, my minimal reproducible example triggers an ICE, reproducable here:https://gcc.godbolt.org/z/vYK3TvE6jThanks a lot for looking at this issue!

------------------------------------------------------------------

template <typename Callable> void helper_func(Callable) {}

template <typename Callable> __attribute__((target_clones("avx2", "default"))) void handler(Callable outer_callback) {
  outer_callback();
}

class InnerClass {
public:
  template <typename Callable> void inner_callback(Callable){};

  void func() {
    helper_func([&](int) {});
    auto outer_callback = [this]() { inner_callback([]() {}); };
    handler(outer_callback);
  }
};

class OuterClass {
public:
  void func();

  InnerClass inner;
};

void OuterClass::func() { inner.func(); }
